SELECT P.ID, P.TITULO, P.SEGUNDO, V.ID VIDEO_ID, V.YT_VIDEO_ID, V.TITULO VIDEO FROM PRATICAS P JOIN VIDEOS V ON V.ID = P.VIDEO_ID WHERE P.CONSELHO = 0 AND V.STATUS = 'ESTUDADO' AND IFNULL(P.JEITO, 'outra') = '{{jeito}}' AND V.ID IN (SELECT XT.VIDEO_ID FROM VIDEO_TEMAS XT WHERE XT.TEMA_ID = {{temaId}}) ORDER BY P.FAVORITA DESC, P.ID DESC LIMIT {{limit}} OFFSET {{offset}}